INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(936,'卢\n先生，我很佩服你，我也很喜欢你。你是个正直的人，你是个有责任担当的人，你说的都是对的，但是你\n说的不能变成现实，也肯定变不成现实。','unknown','','2026-04-28 20:47:56');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(937,'除了黄金之外，有没有其它的对冲手段呢？','unknown','','2026-04-28 20:47:57');
