INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(981,'那你应该发声明','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(982,'不声明，抄就抄呗','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(983,'你是？你是？你是？','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(984,'啊，没事没事。','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(985,'对不起啊，我今天忘带名片，请坐，请坐，请坐。','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(986,'对不起大家,我胃疼。','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(987,'他说抄袭，我抄袭他就我抄袭他，也无所谓呀，他就说抄袭就抄袭吧。','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(988,'这样，三年之后你在学术界、在媒体上还能见到他，他说\n我抄袭有可能是真的呀。如果三年之后他不见了，我还在呢，那就他就是假的了。','unknown','','2026-04-28 20:48:00');
