INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(991,'保障生产、保障供给、保障民生、保障产业生态','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(992,'开始、出发、造反、改变、解放','unknown','','2026-04-28 20:48:00');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(993,'你认为文革的经济原因是什么？为什么会爆发文革，难道仅仅是由于政治上\n的原因吗？','unknown','','2026-04-28 20:48:01');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(994,'卢先生啊，你让买的那些两化股票包括龙头股票，那个负债\n太吓人了，那个盈利太少了。那个技术指标PE呀什么的简直没法看，那你还让我们买？','unknown','','2026-04-28 20:48:01');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(995,'必须得买\n呀！因为它们的负债不是表达它们的问题，是表达它们在蓬勃发展、迅速发展；因为它们有很好的前景，\n才有人借钱给它','unknown','','2026-04-28 20:48:01');
INSERT INTO entities(entity_id,name,entity_type,aliases,created_at) VALUES(996,'如果欧美市场会进入更深层的调整，那么中国的资本市场会怎样动呢？','unknown','','2026-04-28 20:48:01');
